async function loadPropertyCore(){const id=propertyId(),jobs={detail:rpc('bridgepoint_flutter_property_detail_core_v1960',{p_property_id:id}),heartbeat:rpc('bridgepoint_property_heartbeat_v245',{p_property_id:id}),explain:rpc('bridgepoint_property_score_explainability_v1959',{p_property_id:id}),timeline:rpc('bridgepoint_property_timeline_v857',{p_property_id:id,p_limit:180}),notes:rpc('bridgepoint_customer_notes_v70',{p_property_id:id,p_limit:100}),claims:rpc('bridgepoint_claims_workspace_v833',{p_limit:200})},keys=Object.keys(jobs),o=await Promise.allSettled(Object.values(jobs));o.forEach((r,i)=>S.propertyData[keys[i]]=r.status==='fulfilled'?r.value:{error:r.reason?.message||'Unavailable'});const d=obj(S.propertyData.detail),p=obj(d.property||d.identity||d),address=pick(p,'full_address','display_address','address')||pick(S.currentProperty,'full_address','display_address');if(address)$('#propertyAddress').textContent=address;const meta=[pick(p,'municipality','city'),pick(p,'county'),pick(p,'state_code'),pick(p,'postal_code'),pick(p,'parcel_number')].filter(Boolean).join(' · ');if(meta)$('#propertyMeta').textContent=meta;renderPropertyKpis()}
function renderPropertyKpis(){const e=obj(S.propertyData.explain),timeline=firstArray(S.propertyData.timeline),claims=firstArray(S.propertyData.claims).filter(x=>String(pick(x,'property_id'))===String(propertyId())),h=obj(S.propertyData.heartbeat),vals=[['SCORE',pick(e,'score','opportunity_score','current_score','summary.score')??'—'],['TIMELINE',timeline.length],['CLAIMS',claims.length],['SIGNALS',pick(h,'signal_count','signals_count','summary.signal_count')??firstArray(h).length]];$('#propertyKpis').innerHTML=vals.map(([k,v])=>`<article class="counter-card glass"><span>${k}</span><strong>${esc(v)}</strong><small>property intelligence</small></article>`).join('')}
async function ensurePropertyData(key){if(S.propertyData[key])return S.propertyData[key];const id=propertyId(),calls={evidence:['bridgepoint_field_evidence_governance_v1966',{p_property_id:id,p_limit:100}],imagery:['bridgepoint_property_imagery_history_v169',{p_property_id:id}],media:['bridgepoint_property_media_bundle_v169',{p_property_id:id}],site3d:['bridgepoint_property_site_3d_v918',{p_property_id:id,p_radius_m:240,p_limit:900}],geometry:['bridgepoint_property_geometry_v854',{p_property_id:id,p_limit:50}],xray:['bridgepoint_property_xray_core_v1960',{p_property_id:id}],scorechanges:['bridgepoint_score_change_explanation_v141',{p_property_id:id,p_limit:40}]},c=calls[key];if(!c)return null;try{S.propertyData[key]=await rpc(c[0],c[1])}catch(e){S.propertyData[key]={error:e.message}}return S.propertyData[key]}
function timelineHtml(v){const rs=firstArray(v);return rs.length?`<div class="timeline">${rs.slice(0,180).map(x=>`<article class="timeline-item"><small>${esc(fmtDate(pick(x,'occurred_at','event_at','effective_at','detected_at','recorded_at','activity_date','date','created_at')))}</small><h4>${esc(pick(x,'title','event_type','type','signal_name','permit_type','claim_stage')||'Property event')}</h4><p>${esc(pick(x,'summary','description','detail','reason','source_name','status')||'Source-backed property timeline record.')}</p></article>`).join('')}</div>`:structured(v)}
