function imageryHtml(im,media){const items=[];function collect(v,label){if(!v||typeof v!=='object')return;if(Array.isArray(v)){v.forEach(x=>collect(x,label));return}const url=pick(v,'media_url','thumbnail_url','url','image_url','reference_url');if(url&&/^https?:/i.test(String(url)))items.push({...v,_label:label});for(const[k,x]of Object.entries(v))if(x&&typeof x==='object')collect(x,k)}collect(im,'Imagery');collect(media,'Media');const seen=new Set(),u=items.filter(x=>{const z=pick(x,'media_url','thumbnail_url','url','image_url','reference_url');if(seen.has(z))return false;seen.add(z);return true}).slice(0,24);return u.length?`<div class="imagery-grid">${u.map(x=>{const z=String(pick(x,'media_url','thumbnail_url','url','image_url','reference_url')).replaceAll('{{sizeprefix}}','th');return`<article class="media-card"><img src="${esc(z)}" loading="lazy" alt="Property imagery"><b>${esc(titleCase(x._label||'Imagery'))}</b><p>${esc([pick(x,'source_name','provider'),pick(x,'captured_at','image_date','source_year')].filter(Boolean).join(' · '))}</p></article>`}).join('')}</div>`:`<div class="empty-state"><span>◫</span><h3>Imagery records are not available yet.</h3><p>BridgePoint will not fabricate a front photo or historical aerial frame.</p></div>${structured({imagery:im,media})}`}
async function renderProperty3D(site,geo){const host=$('#property3dMap');try{const m=await ensureMapLibre(),c=obj(pick(site,'center')||pick(geo,'centroid')||{}),lat=Number(pick(c,'lat','latitude')??pick(S.currentProperty,'latitude','lat')),lng=Number(pick(c,'lng','longitude')??pick(S.currentProperty,'longitude','lng'));if(!Number.isFinite(lat)||!Number.isFinite(lng))throw new Error('Property location unresolved.');S.twinMap?.remove?.();S.twinMap=new m.Map({container:host,style:rasterStyle('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}','Imagery © Esri'),center:[lng,lat],zoom:18,pitch:64,bearing:-22,maxZoom:21,antialias:true});S.twinMap.addControl(new m.NavigationControl({visualizePitch:true}),'top-right');S.twinMap.on('load',()=>{const features=[];for(const b of [...arr(site,'buildings'),...arr(geo,'geometry')]){const g=pick(b,'geometry');if(g?.type)features.push({type:'Feature',geometry:g,properties:{height:Number(pick(b,'render_height_m','height_m')||8),target:pick(b,'is_target')===true?1:0}})}if(features.length){S.twinMap.addSource('buildings',{type:'geojson',data:{type:'FeatureCollection',features}});S.twinMap.addLayer({id:'buildings3d',type:'fill-extrusion',source:'buildings',paint:{'fill-extrusion-color':['case',['==',['get','target'],1],'#52e6ff','#8398aa'],'fill-extrusion-height':['get','height'],'fill-extrusion-base':0,'fill-extrusion-opacity':.78}})}const parcel=pick(site,'parcel_geometry');if(parcel?.type){S.twinMap.addSource('parcel',{type:'geojson',data:{type:'Feature',geometry:parcel,properties:{}}});S.twinMap.addLayer({id:'parcel-line',type:'line',source:'parcel',paint:{'line-color':'#ffc95e','line-width':3}})}})}catch(e){host.innerHTML=`<div class="empty-state"><span>◫</span><h3>3D scene could not render</h3><p>${esc(e.message)}</p></div>`}}
